arguments.command:
# Let me check - are these addresses actually in the .bss section or .text?
SYMFILE="/tmp/symbols/test.dbg"
aarch64-linux-gnu-readelf -S "$SYMFILE" 2>/dev/null | grep -E "\.text|\.bss|\.rodata" | head -10
echo "---"
# Check section at those VAs
aarch64-linux-gnu-readelf -S "$SYMFILE" 2>/dev/null | awk '{
  if (NF > 5 && $2 ~ /^\./) {
    addr=strtonum("0x"$4); size=strtonum("0x"$6);
    if (addr <= 0x2f4b20 && addr+size > 0x2f4b20) print "0x2f4b20 in " $2 " (addr=0x"$4" size=0x"$6")"
    if (addr <= 0x2f4c84 && addr+size > 0x2f4c84) print "0x2f4c84 in " $2 " (addr=0x"$4" size=0x"$6")"
  }
}'

